      /* (776) show_log_from_tail ::= */ yytestcase(yyruleno==776);
      /* (781) show_profile_type_tail ::= */ yytestcase(yyruleno==781);
      /* (786) show_profile_for_tail ::= */ yytestcase(yyruleno==786);
      /* (802) show_limit_tail ::= */ yytestcase(yyruleno==802);
      /* (814) show_channel_tail ::= */ yytestcase(yyruleno==814);
      /* (816) show_grants_tail ::= */ yytestcase(yyruleno==816);
      /* (818) show_grants_using_tail ::= */ yytestcase(yyruleno==818);
      /* (872) handler_read_suffix ::= */ yytestcase(yyruleno==872);
      /* (882) call_arguments ::= */ yytestcase(yyruleno==882);
      /* (927) flush_table_tail ::= */ yytestcase(yyruleno==927);
      /* (980) table_query_tail ::= */ yytestcase(yyruleno==980);
      /* (983) table_offset_tail ::= */ yytestcase(yyruleno==983);
      /* (988) values_row_contents ::= */ yytestcase(yyruleno==988);
      /* (999) values_query_tail ::= */ yytestcase(yyruleno==999);
      /* (1009) values_order_direction ::= */ yytestcase(yyruleno==1009);
      /* (1015) execute_tail ::= */ yytestcase(yyruleno==1015);
      /* (1038) signal_set_tail ::= */ yytestcase(yyruleno==1038);
      /* (1046) transaction_end_tail ::= */ yytestcase(yyruleno==1046);
      /* (1144) resignal_tail ::= */ yytestcase(yyruleno==1144);
      /* (1158) end_tail ::= */ yytestcase(yyruleno==1158);
      /* (1165) end_label_tail ::= */ yytestcase(yyruleno==1165);
      /* (1167) statement_tail ::= */ yytestcase(yyruleno==1167);
        break;
